I see the issue now. Looking at `filesWithRemainingAgentChanges`:

```go
for _, filePath := range filesTouched {
    // If file wasn't committed at all, it definitely has remaining changes
    if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
        remaining = append(remaining, filePath)  // ← BUG: doesn't check if already in HEAD
        continue
    }
    // ...
}
```

When a file is not in **this** commit's `committedFiles`, it's automatically added to `remaining` without checking if it was already committed in a **previous** commit. This causes files from earlier commits to be incorrectly carried forward.

The fix is to check if the file already exists in HEAD with matching content before adding it to remaining:

input.old_string:
for _, filePath := range filesTouched {
	// If file wasn't committed at all, it definitely has remaining changes
	if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
		remaining = append(remaining, filePath)
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not committed, keeping",
			slog.String("file", filePath),
		)
		continue
	}

input.new_string:
for _, filePath := range filesTouched {
	// If file wasn't committed in THIS commit, check if it's already in HEAD
	// (committed in a previous commit). If content matches shadow branch,
	// it's fully committed and doesn't need carry-forward.
	if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
		// Check if file exists in HEAD (commit tree)
		headFile, headErr := commitTree.File(filePath)
		if headErr == nil {
			// File exists in HEAD - check if it matches shadow branch
			shadowFile, shadowErr := shadowTree.File(filePath)
			if shadowErr == nil && headFile.Hash == shadowFile.Hash {
				// Content matches - file was fully committed in a previous commit
				logging.Debug(logCtx, "filesWithRemainingAgentChanges: file already in HEAD with matching content, skipping",
					slog.String("file", filePath),
				)
				continue
			}
		}
		// File not in HEAD or content doesn't match shadow - needs carry-forward
		remaining = append(remaining, filePath)
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not committed, keeping",
			slog.String("file", filePath),
		)
		continue
	}

